const CHAR_ICONS={character:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8.2 9a3.8 3.8 0 1 1 7.6 0 3.8 3.8 0 0 1-7.6 0Z"/><path d="M4.8 20c.4-4.2 3-6.4 7.2-6.4s6.8 2.2 7.2 6.4"/><path d="M8.7 4.2 12 2.8l3.3 1.4"/></svg>`,strength:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6M7 7v10M17 7v10M20 9v6M7 12h10"/></svg>`,dexterity:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M13.5 5H19v5.5M7 8.5 5 5l3.5 2M15.5 17 19 19l-2-3.5"/></svg>`,constitution:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20s-7-4.3-7-10a4.1 4.1 0 0 1 7-2.9A4.1 4.1 0 0 1 19 10c0 5.7-7 10-7 10Z"/></svg>`,intelligence:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5.2A3.2 3.2 0 0 1 12 4a3.2 3.2 0 0 1 4 1.2A3.1 3.1 0 0 1 18 8a3 3 0 0 1-1 5.7A3.4 3.4 0 0 1 13.4 18H12a3.4 3.4 0 0 1-3.4-4.3A3 3 0 0 1 7 8a3.1 3.1 0 0 1 1-2.8Z"/><path d="M12 4v14M8.7 9.2H12M12 13h4.5"/></svg>`,wisdom:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.8 12s3.4-5 9.2-5 9.2 5 9.2 5-3.4 5-9.2 5-9.2-5-9.2-5Z"/><circle cx="12" cy="12" r="2.5"/></svg>`,charisma:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 1.6 5.2L19 10l-5.4 1.8L12 17l-1.6-5.2L5 10l5.4-1.8L12 3Z"/><path d="M4 4l1.2 1.2M20 4l-1.2 1.2M4 20l1.2-1.2M20 20l-1.2-1.2"/></svg>`,name:`<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.3"/><path d="M5.5 20c.5-4.3 2.8-6.4 6.5-6.4s6 2.1 6.5 6.4"/></svg>`,race:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19.5 4.5C11 5 6.2 9.1 5.3 16.8c5.1.7 10.8-1.7 14.2-12.3Z"/><path d="M5.3 16.8c3.1-2.7 6.4-5.2 10-7.3"/></svg>`,class:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.2 3.7 20 17.5M17.8 3.7 4 17.5M4 17.5l2.5 2.5M20 17.5 17.5 20"/></svg>`,background:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 4h10a2 2 0 0 1 2 2v14H7a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z"/><path d="M9 8h6M9 11.5h6M9 15h4"/></svg>`};const ABILITY_MAP={'СИЛ':'strength','ЛОВ':'dexterity','ТЕЛ':'constitution','ИНТ':'intelligence','МДР':'wisdom','ХАР':'charisma'};function upgradeNav(root=document){root.querySelectorAll('[data-nav="character"] > span').forEach(node=>{if(node.dataset.charIconReady)return;node.dataset.charIconReady='true';node.className='nav-character-icon';node.innerHTML=CHAR_ICONS.character})}function upgradeAbilities(root=document){root.querySelectorAll('.character-page .ability-card, .character-overlay .ability-input').forEach(card=>{const label=card.querySelector('.ability-name, b')?.textContent?.trim()||'',name=ABILITY_MAP[label],slot=card.querySelector('.ability-icon');if(!name||!slot||slot.dataset.charIconReady)return;slot.dataset.charIconReady='true';slot.classList.add('char-vector-icon');slot.innerHTML=CHAR_ICONS[name]})}function upgradeFields(root=document){root.querySelectorAll('.character-overlay .icon-field > span').forEach(label=>{const text=label.textContent?.trim().toLowerCase()||'',key=text.includes('имя')?'name':text.includes('раса')?'race':text.includes('класс')?'class':text.includes('предыст')?'background':'',legacy=label.querySelector('b');if(!key||!legacy||legacy.dataset.charIconReady)return;legacy.dataset.charIconReady='true';legacy.className='field-vector-icon';legacy.innerHTML=CHAR_ICONS[key]})}function upgrade(root=document){upgradeNav(root);upgradeAbilities(root);upgradeFields(root)}upgrade();new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node instanceof HTMLElement)upgrade(node)}).observe(document.documentElement,{childList:true,subtree:true});